const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const N = parseInt(data[0], 10);
const S = data.slice(1, 1 + N).join('');

function increment(s) {
  let arr = s.split('');
  let i = arr.length - 1;
  while (i >= 0 && arr[i] === '9') {
    arr[i] = '0';
    i--;
  }
  if (i < 0) {
    return '1' + arr.join('');
  } else {
    arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1);
    return arr.join('');
  }
}

function isValid(L) {
  let pos = 0;
  let cur = S.slice(0, L);
  while (pos < N) {
    if (pos + cur.length > N) return false;
    for (let i = 0; i < cur.length; i++) {
      if (S[pos + i] !== cur[i]) return false;
    }
    pos += cur.length;
    if (pos === N) return true;
    cur = increment(cur);
  }
  return true;
}

for (let L = 1; L <= N; L++) {
  if (isValid(L)) {
    console.log(S.slice(0, L));
    break;
  }
}
